<template>
  <section class="dinner-card" aria-label="今天吃什么选餐板块">
    <header class="dinner-heading"><span class="dinner-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M5 3v6m3-6v6M3 3v5a3 3 0 0 0 6 0V3M6 11v10M17 3c-3 3-3 7 0 9h3V3h-3Zm3 9v9"/></svg></span><div><span class="dinner-kicker">校园吃饭灵感</span><h4>{{ title }}</h4></div><span class="dinner-total">{{ names.length }} 个候选</span></header>
    <p class="dinner-intro">还没想好？从这份名单里挑一家。<span v-if="card.sourceCount">红榜 {{ card.sourceCount }} 条，全部纳入选餐；麦当劳归入三食堂。</span></p>
    <div class="dinner-channels" aria-label="外卖和食堂筛选"><button v-for="item in channels" :key="item" type="button" :aria-pressed="channel===item" :class="{active:channel===item}" :disabled="disabled" @click="channel=item">{{ item }}</button></div>
    <div class="dinner-categories" aria-label="按店名类别筛选"><button v-for="item in categories" :key="item" type="button" :aria-pressed="category===item" :class="{active:category===item}" :disabled="disabled" @click="category=item">{{ item }}</button></div>
    <div class="dinner-pick" aria-live="polite" aria-atomic="true">
      <template v-if="selected"><span class="dinner-label">{{ confirmed?'今天就吃':'今天不妨试试' }}</span><strong class="dinner-name">{{ selected }}</strong><span class="dinner-kind">{{ dinnerChannel(selected) }}<template v-if="dinnerChannel(selected)==='外卖红榜'"> · {{ categoryFor(selected) }}</template></span><div class="dinner-actions"><button type="button" class="dinner-primary" :disabled="disabled || confirmed" @click="confirmed=true">{{confirmed?'已选好 ✓':'就吃这家'}}</button><button type="button" class="dinner-secondary" :disabled="disabled || filtered.length<2" @click="draw">换一家 <span aria-hidden="true">↻</span></button></div><small v-if="confirmed">选好了，祝你吃得开心。</small></template>
      <template v-else><strong class="dinner-empty">没有找到匹配店家</strong><span>换个关键词或类别试试。</span></template>
    </div>
    <div class="dinner-toolbar"><span>{{ channel==='全部'?(category==='全部'?'全部名单':category):channel }} · {{ filtered.length }} 家</span><button type="button" :aria-expanded="expanded" @click="expanded=!expanded">{{ expanded?'收起店家':'查看全部店家' }} <span aria-hidden="true">{{expanded?'−':'＋'}}</span></button></div>
    <div v-if="expanded" class="dinner-directory"><label class="dinner-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><input v-model="search" type="search" maxlength="80" placeholder="搜索店家名称" aria-label="搜索选餐店家" :disabled="disabled"/></label><div class="dinner-list"><button v-for="name in filtered" :key="name" type="button" :class="{selected:name===selected}" :aria-pressed="name===selected" :disabled="disabled" @click="select(name)"><span>{{ name }}</span><small>{{ dinnerChannel(name) }}</small></button></div><p v-if="!filtered.length" class="dinner-no-results">没有匹配结果，可以清空搜索。</p></div>
    <div v-if="selectedFood" class="dinner-review"><div><span>{{ selectedFood.category }}</span><span v-if="selectedFood.price">价格记录：{{ selectedFood.price }}</span><span v-if="selectedFood.place">{{ selectedFood.place }}</span></div><details :key="selectedFood.id" @toggle="reviewOpened"><summary>查看同学评价</summary><p v-if="reviewLoading" role="status">正在读取评价…</p><p v-else-if="reviewError" role="alert">{{ reviewError }} <button type="button" @click="loadReview">重试读取</button></p><ul v-else><li v-for="(review,i) in selectedReviews" :key="i">{{ review }}</li></ul></details></div>
    <button type="button" class="dinner-browse" :disabled="disabled" @click="$emit('ask','外卖红黑榜')">查看完整红黑榜与有分歧评价 ↗</button>
    <p class="dinner-note">{{ note }}</p>
  </section>
</template>
<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue'
import {get} from '@/api/client'
import {dinnerNames,dinnerCategory,dinnerChannels,dinnerChannel,nextDinner} from '@/utils/dinner-choice'
import {trackCampus} from '@/utils/campus-activity'
const props=defineProps<{card:Record<string,unknown>;disabled?:boolean}>()
defineEmits<{(e:'ask',q:string):void}>()
interface Food {id:number;name:string;category:string;price:string;place:string;reviews?:string[]}
const foods=computed(()=>Array.isArray(props.card.foodItems)?props.card.foodItems.filter((x:any)=>x&&Number.isSafeInteger(x.id)&&typeof x.name==='string'&&typeof x.category==='string') as Food[]:[])
const categoryFor=(name:string)=>foods.value.find(f=>f.name===name)?.category||dinnerCategory(name)
const selectedFood=computed(()=>foods.value.find(f=>f.name===selected.value))
const reviews=ref<Record<number,string[]>>({}),reviewLoading=ref(false),reviewError=ref('');let reviewRequest=0
const selectedReviews=computed(()=>selectedFood.value?.reviews||reviews.value[selectedFood.value?.id??-1]||[])
async function loadReview(){const food=selectedFood.value;if(!food)return;const request=++reviewRequest;reviewError.value='';if(food.reviews||reviews.value[food.id])return;reviewLoading.value=true;try{const result=await get<{items:Food[];enabled:boolean}>('/campus/food',{id:String(food.id)});if(request!==reviewRequest)return;const item=result.items.find(i=>i.id===food.id);if(!item)throw new Error(result.enabled?'该记录已更新，请打开最新红榜':'红榜知识库已停用');reviews.value[food.id]=item.reviews||[]}catch(e:any){if(request===reviewRequest)reviewError.value=e?.message||'评价读取失败'}finally{if(request===reviewRequest)reviewLoading.value=false}}
function reviewOpened(event:Event){if((event.target as HTMLDetailsElement).open&&selectedFood.value){trackCampus('CONTENT_VIEW',{entryId:'food:'+selectedFood.value.id,collection:'takeout',title:selectedFood.value.name});void loadReview()}}
onUnmounted(()=>reviewRequest++)
const names=computed(()=>dinnerNames(props.card.restaurants))
const title=computed(()=>typeof props.card.title==='string'?props.card.title.slice(0,80):'今天吃什么')
const note=computed(()=>typeof props.card.note==='string'?props.card.note.slice(0,500):'按店名分类，营业及配送信息以店家实际情况为准。')
const category=ref('全部'),channel=ref('全部'),search=ref(''),expanded=ref(false),confirmed=ref(false),selected=ref(''),bag=ref<string[]>([])
watch(selected,()=>{reviewRequest++;reviewLoading.value=false;reviewError.value=''})
const channels=computed(()=>dinnerChannels.filter(item=>item==='全部'||names.value.some(name=>dinnerChannel(name)===item)))
const categories=computed(()=>['全部',...new Set(names.value.filter(name=>channel.value==='全部'||dinnerChannel(name)===channel.value).map(categoryFor))])
watch(channel,()=>{category.value='全部';search.value=''})
const normalize=(value:string)=>value.normalize('NFKC').toLowerCase().replace(/\s+/g,'')
const filtered=computed(()=>names.value.filter(name=>(channel.value==='全部'||dinnerChannel(name)===channel.value)&&(category.value==='全部'||categoryFor(name)===category.value)&&normalize(name).includes(normalize(search.value))))
function draw(){if(props.disabled)return;const next=nextDinner(filtered.value,bag.value,selected.value);selected.value=next.name;bag.value=next.remaining;confirmed.value=false}
function select(name:string){if(props.disabled)return;selected.value=name;confirmed.value=false;bag.value=bag.value.filter(item=>item!==name)}
watch(filtered,list=>{bag.value=list.filter(name=>name!==selected.value);confirmed.value=false;if(!list.includes(selected.value)){selected.value=list.includes(String(props.card.initial))?String(props.card.initial):(list[0]||'');bag.value=list.filter(name=>name!==selected.value)}},{immediate:true})
</script>
<style scoped>
.dinner-card{padding:24px;background:var(--nx-surface,var(--el-bg-color));color:var(--nx-text,var(--el-text-color-primary));border:1px solid var(--nx-border,var(--el-border-color));border-radius:20px;margin:16px 0;overflow:hidden}.dinner-heading{display:flex;align-items:center;gap:12px}.dinner-icon{display:grid;place-items:center;width:44px;height:44px;flex-shrink:0;border-radius:14px;background:var(--nx-accent-soft,var(--el-color-primary-light-9));color:var(--nx-accent,var(--el-color-primary))}.dinner-icon svg{width:25px;height:25px}.dinner-kicker{font-size:11px;letter-spacing:1px;color:var(--nx-text-3,var(--el-text-color-secondary))}.dinner-heading h4{font-size:20px;margin:4px 0 0;line-height:1.4;font-weight:650}.dinner-total{margin-left:auto;font-size:11px;color:var(--nx-text-2,var(--el-text-color-secondary));white-space:nowrap}.dinner-intro{font-size:13px;color:var(--nx-text-2,var(--el-text-color-secondary));margin:16px 0}.dinner-categories{display:flex;flex-wrap:wrap;gap:7px}.dinner-card button{font:inherit;cursor:pointer;transition:background .15s,border-color .15s}.dinner-categories button{font-size:11px;background:transparent;color:var(--nx-text-2,var(--el-text-color-secondary));border:1px solid var(--nx-border,var(--el-border-color));border-radius:20px;padding:6px 10px}.dinner-categories button.active{background:var(--nx-accent-soft,var(--el-color-primary-light-9));border-color:var(--nx-accent-border,var(--el-color-primary-light-5));color:var(--nx-accent,var(--el-color-primary))}.dinner-pick{margin:20px 0 16px;min-height:170px;padding:26px 18px;border-radius:16px;background:var(--nx-accent-soft,var(--el-color-primary-light-9));border:1px solid var(--nx-accent-border,var(--el-color-primary-light-7));display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px}.dinner-label{font-size:12px;color:var(--nx-accent,var(--el-color-primary))}.dinner-name{font-size:26px;line-height:1.45;overflow-wrap:anywhere;letter-spacing:-.5px}.dinner-kind,.dinner-pick small,.dinner-pick>span:last-child{font-size:11px;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-actions{display:flex;gap:10px;justify-content:center;margin-top:8px}.dinner-actions button{padding:10px 18px;border-radius:10px;font-size:12px;min-height:40px}.dinner-primary{background:var(--nx-accent,var(--el-color-primary));color:var(--nx-text-invert,#fff);border:1px solid var(--nx-accent,var(--el-color-primary))}.dinner-secondary{background:var(--nx-surface,var(--el-bg-color));color:var(--nx-text,var(--el-text-color-primary));border:1px solid var(--nx-border,var(--el-border-color))}.dinner-secondary span{margin-left:5px}.dinner-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-toolbar button{background:transparent;border:0;padding:8px 0;color:var(--nx-accent,var(--el-color-primary));font-size:12px}.dinner-directory{margin-top:12px}.dinner-search{display:flex;gap:9px;align-items:center;padding:10px 12px;border:1px solid var(--nx-border,var(--el-border-color));background:var(--nx-surface-2,var(--el-fill-color-light));border-radius:10px}.dinner-search svg{width:18px;height:18px;flex-shrink:0;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-search input{min-width:0;flex:1;background:transparent;border:0;outline:0;font:inherit;font-size:13px;color:inherit}.dinner-search input::placeholder{color:var(--nx-text-3,var(--el-text-color-placeholder))}.dinner-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:330px;overflow:auto;overscroll-behavior:contain;padding:12px 2px 2px;scrollbar-width:thin}.dinner-list button{display:flex;flex-direction:column;gap:6px;text-align:left;padding:12px;border-radius:10px;background:var(--nx-surface-2,var(--el-fill-color-light));color:inherit;border:1px solid var(--nx-border,var(--el-border-color));font-size:12px;overflow-wrap:anywhere}.dinner-list button.selected{border-color:var(--nx-accent,var(--el-color-primary));background:var(--nx-accent-soft,var(--el-color-primary-light-9))}.dinner-list small{font-size:10px;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-note{margin:18px 0 0;padding-top:14px;border-top:1px solid var(--nx-border,var(--el-border-color));font-size:10px;line-height:1.8;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-card button:focus-visible,.dinner-search:focus-within{outline:2px solid var(--nx-accent,var(--el-color-primary));outline-offset:3px}.dinner-card button:disabled{opacity:.55;cursor:default}.dinner-empty{font-size:17px;margin-top:25px}.dinner-no-results{font-size:12px;color:var(--nx-text-2,var(--el-text-color-secondary));text-align:center;padding:15px}@media(max-width:480px){.dinner-card{padding:18px 14px;border-radius:16px}.dinner-name{font-size:22px}.dinner-heading h4{font-size:18px}.dinner-total{font-size:10px}.dinner-categories{gap:6px}.dinner-categories button{padding:6px 9px}.dinner-list{grid-template-columns:1fr}.dinner-pick{padding:24px 12px}}

.dinner-channels{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 14px}.dinner-channels button{padding:8px 12px;border-radius:10px;border:1px solid var(--nx-border,var(--el-border-color));background:var(--nx-surface-2,var(--el-fill-color-light));color:var(--nx-text-2,var(--el-text-color-secondary));font-size:12px}.dinner-channels button.active{background:var(--nx-accent,var(--el-color-primary));border-color:var(--nx-accent,var(--el-color-primary));color:var(--nx-text-invert,#fff)}
</style>

<style scoped>.dinner-review{margin:15px 0;padding:14px;border:1px solid var(--nx-border,var(--el-border-color));border-radius:12px;font-size:12px;line-height:1.8}.dinner-review>div{display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--nx-text-2,var(--el-text-color-secondary))}.dinner-review summary{cursor:pointer;color:var(--nx-accent,var(--el-color-primary));margin-top:8px}.dinner-review ul{padding-left:18px}.dinner-browse{padding:9px 0;border:0;background:transparent;color:var(--nx-accent,var(--el-color-primary));font-size:12px}</style>
